def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = b
        else:
            chain_dict[a] = chain_dict[b]

    current = chain_dict['aaa']
    result = []
    while current:
        result.append(current)
        current = chain_dict[current]

    return ','.join(result)

# Example usage:
# print(chain_follow(['bbb', 'ccc']))  # Output: aaa, bbb, ccc, ddd
